// Chuan bi du lieu cho Supabase - map dung schema bang interview_evaluations
const b = $input.first().json.body;

// Gom cac cau hoi tinh huong (dang phang) thanh mang JSON cho cot situations (jsonb)
const situations = [];
for (const i of [1, 2, 3, 4, 5, 6, 11, 12, 13, 14, 15]) {
  if (b['sit_' + i + '_question']) {
    situations.push({
      cau_hoi: b['sit_' + i + '_question'],
      cau_tra_loi: b['sit_' + i + '_answer'] || 'Chưa hỏi / Không có câu trả lời',
      danh_gia: b['sit_' + i + '_tags'] || ''
    });
  }
}

// Convert ngay dd/MM/yyyy -> yyyy-MM-dd (kieu date cua Postgres)
let interviewDate = null;
if (b.interview_date) {
  const p = String(b.interview_date).split('/');
  if (p.length === 3) interviewDate = p[2] + '-' + p[1] + '-' + p[0];
}

// Parse so an toan (form gui string)
function num(v) {
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}

return [{
  json: {
    company: b.company || null,
    student_name: b.student_name || null,
    profession: b.profession || null,
    destination: b.destination || null,
    interview_date: interviewDate,
    evaluator: b.evaluator || null,
    certificate: b.certificate || null,
    age: b.age || null,
    hometown: b.hometown || null,
    family_in_germany: b.family_in_germany || null,
    family_region: b.family_region || null,
    score_pronunciation: num(b.score_pronunciation),
    score_listening: num(b.score_listening),
    score_content: num(b.score_content),
    score_situation: num(b.score_situation),
    score_attitude: num(b.score_attitude),
    score_adjustment: num(b.score_adjustment) === null ? 0 : num(b.score_adjustment),
    adjustment_reason: b.adjustment_reason || null,
    total_score: num(b.total_score),
    final_score: num(b.final_score),
    detail_pronunciation: b.detail_pronunciation || null,
    detail_listening: b.detail_listening || null,
    detail_content: b.detail_content || null,
    detail_attitude: b.detail_attitude || null,
    note_pronunciation: b.note_pronunciation || null,
    note_listening: b.note_listening || null,
    note_content: b.note_content || null,
    note_attitude: b.note_attitude || null,
    strengths: b.strengths || null,
    improvements: b.improvements || null,
    notes: b.notes || null,
    verdict: b.verdict || null,
    situations: situations
  }
}];

